import csv

# Check all transactions for account 2779
operations = {}
with open('csv/trans.csv', 'r') as f:
    reader = csv.DictReader(f)
    for row in reader:
        if row['account_id'] == '2779':
            op = row['operation']
            if op not in operations:
                operations[op] = 0
            operations[op] += 1

print('Operations for account 2779:')
for op, count in sorted(operations.items()):
    print(f'{op}: {count} transactions')
print(f'Total transactions: {sum(operations.values())}')

